package com.srm.inventory.service;
import com.srm.inventory.entity.Product; import com.srm.inventory.repository.ProductRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ProductService { private final ProductRepository repo; public ProductService(ProductRepository r){repo=r;} public List<Product> list(String q, Boolean low){ if(Boolean.TRUE.equals(low)) return repo.findAll().stream().filter(p->p.getStockQuantity()<=p.getReorderLevel()).toList(); return q==null||q.isBlank()?repo.findAll():repo.findByNameContainingIgnoreCaseOrSkuContainingIgnoreCase(q,q); } public Product get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Product not found"));} public Product save(Product p){ if(repo.existsBySkuAndIdNot(p.getSku(),p.getId()==null?-1L:p.getId())) throw new IllegalArgumentException("SKU already exists"); return repo.save(p);} public void delete(Long id){repo.delete(get(id));} }
